svg.script:
(() => {
  const svg = document.documentElement;
  const period = 1200;
  const crankX = 785;
  const crankY = 630;
  const pedalRadius = 72;
  const start = performance.now();
  let paused = false;
  let pausedAt = 0;
  let accumulatedPause = 0;
  let raf = 0;

  const nodes = {
    body: document.getElementById('pelicanBody'),
    frontUpper: document.getElementById('frontUpper'),
    frontUpperShade: document.getElementById('frontUpperShade'),
    frontLower: document.getElementById('frontLower'),
    frontScaleMarks: document.getElementById('frontScaleMarks'),
    frontKnee: document.getElementById('frontKnee'),
    frontFoot: document.getElementById('frontFoot'),
    backUpper: document.getElementById('backUpper'),
    backUpperShade: document.getElementById('backUpperShade'),
    backLower: document.getElementById('backLower'),
    backKnee: document.getElementById('backKnee'),
    backFoot: document.getElementById('backFoot'),
    crankFront: document.getElementById('crankArmFront'),
    crankBack: document.getElementById('crankArmBack'),
    pedalFront: document.getElementById('pedalFront'),
    pedalBack: document.getElementById('pedalBack'),
    control: document.getElementById('control'),
    controlText: document.getElementById('controlText'),
    pauseIcon: document.getElementById('pauseIcon'),
    playIcon: document.getElementById('playIcon')
  };

  function solveKnee(hip, foot, upper, lower, preferRight) {
    const dx = foot.x - hip.x;
    const dy = foot.y - hip.y;
    const rawDist = Math.hypot(dx, dy);
    const dist = Math.max(1, Math.min(rawDist, upper + lower - .001));
    const along = (upper * upper - lower * lower + dist * dist) / (2 * dist);
    const height = Math.sqrt(Math.max(0, upper * upper - along * along));
    const ux = dx / rawDist;
    const uy = dy / rawDist;
    const baseX = hip.x + along * ux;
    const baseY = hip.y + along * uy;
    const a = { x: baseX - height * uy, y: baseY + height * ux };
    const b = { x: baseX + height * uy, y: baseY - height * ux };
    return preferRight ? (a.x > b.x ? a : b) : (a.x < b.x ? a : b);
  }

  function setLine(line, x1, y1, x2, y2) {
    line.setAttribute('x1', x1.toFixed(2));
    line.setAttribute('y1', y1.toFixed(2));
    line.setAttribute('x2', x2.toFixed(2));
    line.setAttribute('y2', y2.toFixed(2));
  }

  function setLeg(prefix, hip, foot, upper, lower, preferRight, footAngle) {
    const knee = solveKnee(hip, foot, upper, lower, preferRight);
    const upperD = `M${hip.x.toFixed(2)} ${hip.y.toFixed(2)} Q${((hip.x + knee.x) / 2 - 3).toFixed(2)} ${((hip.y + knee.y) / 2 - 4).toFixed(2)} ${knee.x.toFixed(2)} ${knee.y.toFixed(2)}`;
    const lowerD = `M${knee.x.toFixed(2)} ${knee.y.toFixed(2)} Q${((knee.x + foot.x) / 2 + 4).toFixed(2)} ${((knee.y + foot.y) / 2).toFixed(2)} ${foot.x.toFixed(2)} ${foot.y.toFixed(2)}`;
    nodes[prefix + 'Upper'].setAttribute('d', upperD);
    nodes[prefix + 'UpperShade'].setAttribute('d', upperD);
    nodes[prefix + 'Lower'].setAttribute('d', lowerD);
    if (prefix === 'front') nodes.frontScaleMarks.setAttribute('d', lowerD);
    nodes[prefix + 'Knee'].setAttribute('cx', knee.x.toFixed(2));
    nodes[prefix + 'Knee'].setAttribute('cy', knee.y.toFixed(2));
    nodes[prefix + 'Foot'].setAttribute('transform',
      `translate(${foot.x.toFixed(2)} ${foot.y.toFixed(2)}) rotate(${footAngle.toFixed(2)})`);
  }

  function render(now) {
    const t = paused ? pausedAt - start - accumulatedPause : now - start - accumulatedPause;
    const phase = ((t % period) / period) * Math.PI * 2 - Math.PI / 2;
    const bob = Math.sin(phase * 2) * 2.8 + Math.sin(phase) * .7;
    const bodyTilt = Math.sin(phase * 2) * .38;
    nodes.body.setAttribute('transform', `translate(0 ${bob.toFixed(2)}) rotate(${bodyTilt.toFixed(3)} 728 440)`);

    const frontPedal = {
      x: crankX + Math.cos(phase) * pedalRadius,
      y: crankY + Math.sin(phase) * pedalRadius
    };
    const backPedal = {
      x: crankX - Math.cos(phase) * pedalRadius,
      y: crankY - Math.sin(phase) * pedalRadius
    };

    setLine(nodes.crankFront, crankX, crankY, frontPedal.x, frontPedal.y);
    setLine(nodes.crankBack, crankX, crankY, backPedal.x, backPedal.y);
    nodes.pedalFront.setAttribute('transform', `translate(${frontPedal.x.toFixed(2)} ${frontPedal.y.toFixed(2)})`);
    nodes.pedalBack.setAttribute('transform', `translate(${backPedal.x.toFixed(2)} ${backPedal.y.toFixed(2)})`);

    const frontHip = { x: 747, y: 451 + bob };
    const backHip = { x: 704, y: 455 + bob };
    const frontFoot = { x: frontPedal.x - 3, y: frontPedal.y - 10 };
    const backFoot = { x: backPedal.x - 2, y: backPedal.y - 9 };
    setLeg('front', frontHip, frontFoot, 147, 126, true, -4 + Math.cos(phase) * 9);
    setLeg('back', backHip, backFoot, 143, 122, true, -5 - Math.cos(phase) * 8);

    svg.dataset.phase = (((phase + Math.PI / 2) / (Math.PI * 2)) % 1).toFixed(3);
    svg.dataset.running = String(!paused);
    if (!paused) raf = requestAnimationFrame(render);
  }

  function togglePlayback() {
    if (paused) {
      accumulatedPause += performance.now() - pausedAt;
      paused = false;
      svg.classList.remove('paused');
      svg.unpauseAnimations();
      nodes.controlText.textContent = 'PAUSE';
      nodes.control.setAttribute('aria-label', '暂停动画');
      nodes.pauseIcon.setAttribute('display', 'inline');
      nodes.playIcon.setAttribute('display', 'none');
      render(performance.now());
    } else {
      pausedAt = performance.now();
      paused = true;
      cancelAnimationFrame(raf);
      svg.classList.add('paused');
      svg.pauseAnimations();
      nodes.controlText.textContent = 'PLAY';
      nodes.control.setAttribute('aria-label', '继续播放动画');
      nodes.pauseIcon.setAttribute('display', 'none');
      nodes.playIcon.setAttribute('display', 'inline');
      render(pausedAt);
    }
  }

  nodes.control.addEventListener('click', togglePlayback);
  nodes.control.addEventListener('keydown', (event) => {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      event.stopPropagation();
      togglePlayback();
    }
  });
  window.addEventListener('keydown', (event) => {
    if (event.code === 'Space') {
      event.preventDefault();
      togglePlayback();
    }
  });

  window.__pelicanAnimation = {
    toggle: togglePlayback,
    pause: () => { if (!paused) togglePlayback(); },
    play: () => { if (paused) togglePlayback(); },
    state: () => ({ running: !paused, phase: Number(svg.dataset.phase || 0) })
  };

  raf = requestAnimationFrame(render);
})();
